; bits (here i72) used to hit assert(ArgOuts.size() == 1) in LowerCall because
; shouldPassAsArray() only caught widths >= 128. The call site must declare a
; single .param .b128 and carry the two legalized i64 pieces via v2.b64.
declare i72 @i72_call_callee(i72 %x)

; CHECK-LABEL: .visible .func (.param .b128 func_retval0) i72_call_argouts_size_assert(
; CHECK-NEXT: .param .b128 i72_call_argouts_size_assert_param_0
define i72 @i72_call_argouts_size_assert(i72 %x) {
  ; CHECK: ld.param.v2.b64 {%[[REG0:rd[0-9]+]], %[[REG1:rd[0-9]+]]}, [i72_call_argouts_size_assert_param_0];
  ; CHECK: { // callseq 0, 0
  ; CHECK-DAG: .param .b128 param0;
  ; CHECK-DAG: .param .b128 retval0;
  ; CHECK: st.param.v2.b64 [param0], {%[[REG0]], %[[REG1]]};
  ; CHECK: call.uni (retval0), i72_call_callee,
  ; CHECK: ld.param.v2.b64 {%[[REG2:rd[0-9]+]], %[[REG3:rd[0-9]+]]}, [retval0];
  ; CHECK: } // callseq 0
  %r = call i72 @i72_call_callee(i72 %x)
  ; CHECK: st.param.v2.b64 [func_retval0], {%[[REG2]], %[[REG3]]};
  ret i72 %r
}

