; ptrtoint, i.e. add/sub of ptrtoint(@sym). Previously crashed bufferLEByte with
; llvm_unreachable("unsupported integer const type"); now emitted as sym+offset.
; CHECK-DAG: .u64 aggsym_ptrtoint_addsub[3] = {aggsym_g, aggsym_g+16, aggsym_g-8};
