@aggsym_ptrtoint_addsub = addrspace(1) global [3 x i64] [
  i64 ptrtoint (ptr addrspace(1) @aggsym_g to i64),
  i64 add (i64 ptrtoint (ptr addrspace(1) @aggsym_g to i64), i64 16),
  i64 sub (i64 ptrtoint (ptr addrspace(1) @aggsym_g to i64), i64 8)
]

