; Regression test for bug 033: atomicrmw fadd float must NOT lower to the
; always-subnormal-flushing native atom.add.f32 in default (ieee) denormal
; mode. It must expand to a CAS loop using the non-flushing add.rn.f32, so
; subnormal inputs/results are preserved as IEEE semantics require.
define float @fadd_f32_ieee_expand_cas(ptr %p, float %v) {
; SM90-LABEL: fadd_f32_ieee_expand_cas(
; SM90:       {
; SM90-NEXT:    .reg .pred %p<2>;
; SM90-NEXT:    .reg .b32 %r<5>;
; SM90-NEXT:    .reg .b64 %rd<2>;
; SM90-EMPTY:
; SM90-NEXT:  // %bb.0:
; SM90-NEXT:    ld.param.b32 %r2, [fadd_f32_ieee_expand_cas_param_1];
; SM90-NEXT:    ld.param.b64 %rd1, [fadd_f32_ieee_expand_cas_param_0];
; SM90-NEXT:    ld.relaxed.sys.b32 %r4, [%rd1];
; SM90-NEXT:  $L__BB[[#]]_1: // %atomicrmw.start
; SM90-NEXT:    // =>This Inner Loop Header: Depth=1
; SM90-NEXT:    add.rn.f32 %r3, %r4, %r2;
; SM90-NEXT:    atom.relaxed.sys.cas.b32 %r1, [%rd1], %r4, %r3;
; SM90-NEXT:    setp.ne.b32 %p1, %r1, %r4;
; SM90-NEXT:    mov.b32 %r4, %r1;
; SM90-NEXT:    @%p1 bra $L__BB[[#]]_1;
; SM90-NEXT:  // %bb.2: // %atomicrmw.end
; SM90-NEXT:    st.param.b32 [func_retval0], %r1;
; SM90-NEXT:    ret;
  %r = atomicrmw fadd ptr %p, float %v monotonic
  ret float %r
}

; Companion: with f32 denormal output mode = preserve-sign (FTZ), the native
; always-flushing atom.add.f32 is correct and should still be selected.
define float @fadd_f32_ftz_native(ptr %p, float %v) #0 {
; SM90-LABEL: fadd_f32_ftz_native(
; SM90:    atom.relaxed.sys.add.f32 %r2, [%rd1], %r1;
  %r = atomicrmw fadd ptr %p, float %v monotonic
  ret float %r
}

attributes #0 = { denormal_fpenv(float: preservesign) }

