; A blockaddress nested in an aggregate global must emit the block-address
; relocation (the $L__tmp label), not all-zero bytes.
; CHECK-DAG: .u64 blockaddr_aggregate_arr[1] = {$L__tmp{{[0-9]+}}};
@blockaddr_aggregate_arr = global [1 x ptr] [ptr blockaddress(@blockaddr_aggregate_bar, %lbl)]

define void @blockaddr_aggregate_bar() {
entry:
  br label %lbl
lbl:
  ret void
}

; A scalar `ptr` global initialized to a blockaddress used to crash the
; AsmPrinter (printScalarConstant llvm_unreachable). It must now emit the
; global initializer as a reference to the block-address label.
; CHECK-DAG: .global .align 8 .u64 blockaddr_global_ba = $L__tmp[[#]];
@blockaddr_global_ba = global ptr blockaddress(@blockaddr_global_fn, %lbl)

define void @blockaddr_global_fn() {
entry:
  br label %lbl
; CHECK-DAG: $L__tmp[[#]]:{{.*}}Block address taken
lbl:
  ret void
}

